            properties: BTreeMap::new(),
            string_properties: BTreeMap::new(),
            token_properties: BTreeMap::new(),
            list_properties: BTreeMap::new(),
            text_binding: None,
            property_bindings: BTreeMap::new(),
            string_bindings: BTreeMap::new(),
            media_controller: None,
