    /// use std::rc::Rc;
    /// use pathland_view::{vstack, text, Engine, MediaController, MediaControllerExt, View};
    ///
    /// let engine = Engine::new();
    /// let player = Rc::new(MediaController::with_source(&engine.runtime(), "/assets/track1.mp3"));
