    fn attach(self: &Rc<Self>) -> MediaControllerAttach;
}

impl MediaControllerExt for MediaController {
    fn attach(self: &Rc<Self>) -> MediaControllerAttach {
        MediaControllerAttach(Rc::clone(self))
    }
}

