            transport.deliver(FrameCodec.encodeFrame(new ProtocolFrame(List.of(
                    new Opcode(Categories.PARAMETER, Commands.Parameter.SET_TEXT, 0, 2, 0, 0)),
                    stringSection("x"))));
        }
